'use strict';
const assert=require('assert/strict'),fs=require('fs'),path=require('path'),crypto=require('crypto'),E=require('./core.js');
const root=path.resolve(__dirname,'..'),rom=fs.readFileSync(path.join(root,'build/naruto_role_swap_v0.1.5_EXPERIMENTAL.gba'));
const hash=b=>crypto.createHash('sha256').update(b).digest('hex'),checks=[];
function check(name,fn){fn();checks.push({name,result:'pass'});}
const fresh=()=>new E.Editor(rom,'v015.gba'),font=()=>Uint8Array.from({length:32},()=>0x33);
check('no_edit_export_is_byte_identical',()=>assert.equal(hash(fresh().build(font)),hash(rom)));
check('different_game_is_rejected',()=>{let b=Buffer.from(rom);b[0xac]=0;assert.throws(()=>new E.Editor(b));});
check('all_55_scenario_graphs_parse_without_unknown_instructions',()=>{const m=fresh();for(let i=1;i<=55;i++)assert.deepEqual(m.scripts(i).issues,[]);});
check('all_stage_actor_and_condition_regions_are_in_bounds',()=>{const m=fresh();for(let s=1;s<=46;s++)for(let sub=0;sub<3;sub++){assert.equal(m.actors(s,sub).length,12);assert.equal(m.objects(s,sub).length,16);assert.equal(m.rules(s,sub).groups.flat().length,8);assert.equal(m.missionTexts(s,sub).length,3);}});
check('actor_identity_change_carries_the_new_character_skills',()=>{const m=fresh(),a=m.actors(1,0)[4];m.transaction('enemy',()=>m.setActor(1,0,4,{...a,id:18,level:2,x:10}));const b=m.build(font),q=new E.Editor(b);assert.equal(q.actors(1,0)[4].id,18);assert.equal(q.actors(1,0)[4].level,2);assert.equal(q.actors(1,0)[4].x,10);assert.notDeepEqual(b.slice(a.offset+16,a.offset+76),rom.slice(a.offset+16,a.offset+76));});
check('position_change_preserves_role_template_and_persistent_mod_code',()=>{const m=fresh(),a=m.actors(1,0)[0];m.transaction('position',()=>m.setActor(1,0,0,{...a,x:a.x-1}));const b=m.build(font);assert.equal(b[a.offset+2],a.x-1);for(let p=0;p<rom.length;p++)if(p!==a.offset+2)assert.equal(b[p],rom[p],`Unexpected change ${p.toString(16)}`);m.undo();assert.equal(hash(m.build(font)),hash(rom));});
check('invalid_actor_edit_rolls_back',()=>{const m=fresh(),a=m.actors(1,0)[0];assert.throws(()=>m.transaction('bad',()=>m.setActor(1,0,0,{...a,id:12,x:300})));assert.equal(m.edits.size,0);});
check('role_changed_to_enemy_has_nonempty_attack_skills',()=>{const m=fresh(),a=m.actors(1,0)[0];m.setActor(1,0,0,{...a,side:1});const b=m.build(font);assert(b.slice(a.offset+16,a.offset+76).some(v=>v));});
check('copied_rule_and_custom_description_survive_project_roundtrip',()=>{const m=fresh();m.transaction('copy',()=>{m.copyRule(1,0,0,2,0);m.setText(m.ruleText(m.rules(1,0).groups[0][2]),'WIN');});const project=m.project(hash(rom)),q=fresh();q.importProject(project,hash(rom));assert.equal(hash(q.build(font)),hash(m.build(font)));});
check('mismatched_project_is_rejected_without_mutation',()=>{const m=fresh(),q=m.project('wrong');assert.throws(()=>m.importProject(q,hash(rom)));assert.equal(m.edits.size,0);});
let dialogueResult;
check('long_dialogue_pages_and_speaker_are_written_as_reachable_native_commands',()=>{const m=fresh(),entry=m.dialogues(1).find(e=>e.op===1&&e.length>=5);m.setText(entry,'新对白。\nNPC A【分页】第二页。',21);dialogueResult=m.build(font);assert.equal(dialogueResult[entry.offset],7);const q=new E.Editor(dialogueResult),g=q.scripts(1),dest=E.u32(dialogueResult,entry.offset+1)-E.BASE;assert.equal(dialogueResult[dest],2);assert.equal(dialogueResult[dest+2],21);assert(g.nodes.some(n=>n.offset===dest+6&&n.op===1));const pages=q.dialogues(1).filter(e=>e.offset>=rom.length);assert.equal(pages.length,2);assert(q.textValue(pages[0]).includes('新对白'));assert(q.textValue(pages[1]).includes('第二页'));});
check('unknown_raw_glyph_and_invalid_control_codes_are_rejected',()=>{const m=fresh();assert.throws(()=>m.tokenize('{字FFFF}'));assert.throws(()=>m.tokenize('{#0100FF}'));});
check('IPS_reconstructs_the_exact_edited_ROM',()=>{const patch=E.ips(rom,dialogueResult);let data=Array.from(rom),p=5;while(!(patch[p]===69&&patch[p+1]===79&&patch[p+2]===70)){let off=patch[p]*65536+patch[p+1]*256+patch[p+2],n=patch[p+3]*256+patch[p+4];p+=5;assert(n);for(let i=0;i<n;i++)data[off+i]=patch[p+i];p+=n;}assert.equal(hash(Buffer.from(data)),hash(dialogueResult));});
check('title_credit_patches_remain_unchanged_after_dialogue_edit',()=>{for(const[p,n]of [[0x8bd30,4],[0x8bd38,4],[0x8bbea,2],[0x8bbf2,2],[0x8bd44,4]])assert.deepEqual(dialogueResult.slice(p,p+n),new Uint8Array(rom.slice(p,p+n)));});
check('original_example_contains_only_new_scene_one_dialogue_and_conditions',()=>{const m=new E.Editor(fs.readFileSync(path.join(root,'build/naruto_fog_harbor_sample_v0.1.0.gba')));assert.equal(m.dialogues(1).length,19);assert.equal(m.scripts(1).issues.length,0);for(let sub=0;sub<3;sub++){const r=m.rules(1,sub);assert.equal(r.turn,0);assert.deepEqual(r.groups.map(g=>g.filter(x=>x.type).length),[1,1]);assert.equal(m.textValue(m.ruleText(r.groups[0][0])),'击退两名破坏者');assert.equal(m.textValue(m.ruleText(r.groups[1][0])),'我方全员倒下');assert(m.textValue(m.missionTexts(1,sub)[0]).includes('雾港信标'));}});
const output={checks,kind:'static ROM parser, writer, project and IPS tests; runtime acceptance is recorded separately'};
fs.writeFileSync(path.join(process.env.NARUTO_EDITOR_TEST_OUT||path.join(root,'evidence/editor_v010'),'core_tests.json'),JSON.stringify(output,null,2));console.log(`${checks.length} checks passed`);
